<?php
class OrdenController extends Controller {public function index():void{Auth::requireLogin();$this->view('ordenes/index',['title'=>'Órdenes de servicio','rows'=>(new OrdenServicio())->all()]);}public function form():void{Auth::requireRole(['administrador','recepcion']);$this->view('ordenes/form',['title'=>'Nueva orden','opt'=>(new OrdenServicio())->options()]);}public function save():void{Auth::requireRole(['administrador','recepcion']);(new OrdenServicio())->create($_POST);Session::flash('ok','Orden creada.');$this->redirect('ordenes');}public function detail():void{Auth::requireLogin();$this->view('ordenes/view',['title'=>'Detalle de orden','row'=>(new OrdenServicio())->find($this->id()),'opt'=>(new OrdenServicio())->options()]);}public function update():void{Auth::requireRole(['administrador','tecnico']);(new OrdenServicio())->updateWork((int)$_POST['id'],$_POST);Session::flash('ok','Trabajo técnico actualizado.');$this->redirect('ordenes/view?id='.(int)$_POST['id']);}}
